#include <memory>
#include <iostream>
#include <memory>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual void print() const = 0;
};

class Circle : public Shape {
public:
    explicit Circle(double r) : radius{r} {}
    double area() const override {
        return 3.141592653589793 * radius * radius;
    }
    void print() const override {
        std::cout << "Circle(r=" << radius << ", area=" << area() << ")\n";
    }
private:
    double radius{0.0};
};

class Square : public Shape {
public:
    explicit Square(double s) : side{s} {}
    double area() const override {
        return side * side;
    }
    void print() const override {
        std::cout << "Square(s=" << side << ", area=" << area() << ")\n";
    }
private:
    double side{0.0};
};

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(3.0));
    shapes.push_back(std::make_unique<Square>(4.0));

    for (const auto& shapePtr : shapes) {
        shapePtr->print();
    }
    return 0;
}

#include <memory>
#include <iostream>
#include <string>
#include <vector>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName{std::move(first)}, lastName{std::move(last)}, socialSecurityNumber{std::move(ssn)} {}
    virtual ~Employee() = default;

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSSN() const { return socialSecurityNumber; }

    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << firstName << " " << lastName << " (SSN: " << socialSecurityNumber << ")";
    }
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(std::string first, std::string last, std::string ssn, double salary)
        : Employee{std::move(first), std::move(last), std::move(ssn)}, weeklySalary{salary} {}

    double earnings() const override { return weeklySalary; }
    void print() const override {
        std::cout << "Salaried employee: ";
        Employee::print();
        std::cout << "\n  Weekly salary: $" << weeklySalary;
    }
private:
    double weeklySalary{0.0};
};

int main() {
    std::vector<std::unique_ptr<Employee>> employees;
    employees.push_back(std::make_unique<SalariedEmployee>("John", "Smith", "111-11-1111", 800.00));

    for (const auto& emp : employees) {
        emp->print();
        std::cout << "\n  Earnings: $" << emp->earnings() << "\n";
    }
    return 0;
}
